import type { CatalogItem, Category, CountBy } from "./types.ts";

/**
 * Goods usually sold in Cameroon's provision shops, kiosks and market stalls,
 * with the know-how a shopkeeper has about each: how to tell it apart, how to
 * size it, what shape the detector should look for and how it is counted.
 * Prices are rough FCFA ranges per selling unit (Douala, 2026) used only to
 * flag a spoken price that cannot be right.
 */

type Partial = Pick<CatalogItem, "id" | "name" | "category" | "shape" | "unit"> & Omit<globalThis.Partial<CatalogItem>, "id" | "name" | "category" | "shape" | "unit">;

const SOFT_SHAPES = new Set(["package", "sachet", "packet", "pack", "bag", "sack", "pouch"]);

function g(p: Partial): CatalogItem {
  return {
    names: [],
    brand: "",
    marks: [],
    look: "",
    lookAlikes: [],
    tellApart: "",
    sizes: [],
    sizeCue: "",
    fallback: p.shape === "package" ? "packet" : SOFT_SHAPES.has(p.shape) ? "package" : "container",
    soft: SOFT_SHAPES.has(p.shape),
    display: "on a shelf",
    countBy: "unit" as CountBy,
    countNotes: "",
    ...p,
  };
}

